"use client";

import * as React from "react";
import {
  EASE_OUT,
  INTERACTION_FOCUS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * TOGGLE GROUP: several on/off choices side by side
 *
 *   press    each toggle fills when it's on and empties when off
 *   merge    toggles that are on next to each other join into one
 *            shape: the corners between them square off, so Bold +
 *            Italic read as one pill instead of two blobs
 *   single   <Toggle> on its own is one pressed/unpressed button
 *
 * For one choice out of several, use the segmented control.
 * ───────────────────────────────────────────────────────── */

export interface ToggleOption {
  value: string;
  label: string;
  icon?: React.ReactNode;
  /** Show only the icon; `label` becomes the accessible name. */
  iconOnly?: boolean;
  disabled?: boolean;
}

export interface ToggleGroupProps {
  options: ToggleOption[];
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (value: string[]) => void;
  /** Accessible name of the group. */
  label: string;
  size?: "sm" | "md";
  className?: string;
}

const R = 999;

export function ToggleGroup({
  options,
  value,
  defaultValue = [],
  onValueChange,
  label,
  size = "md",
  className = "",
}: ToggleGroupProps) {
  const reduced = useInteractionReducedMotion();
  const [own, setOwn] = React.useState(defaultValue);
  const on = value ?? own;
  const sm = size === "sm";

  const flip = (v: string) => {
    const next = on.includes(v) ? on.filter((x) => x !== v) : [...on, v];
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
  };

  return (
    <div
      role="group"
      aria-label={label}
      className={`inline-flex items-center rounded-full bg-card p-0.5 shadow-[inset_0_0_0_1px_var(--border)] ${className}`}
    >
      {options.map((o, i) => {
        const pressed = on.includes(o.value);
        const left = pressed && on.includes(options[i - 1]?.value ?? "");
        const right = pressed && on.includes(options[i + 1]?.value ?? "");
        return (
          <button
            key={o.value}
            type="button"
            aria-pressed={pressed}
            aria-label={o.iconOnly ? o.label : undefined}
            disabled={o.disabled}
            onClick={() => flip(o.value)}
            className={`group/tg relative inline-flex shrink-0 items-center justify-center gap-1.5 font-medium cursor-pointer disabled:cursor-default disabled:opacity-40 [&_svg]:size-3.5 ${
              sm ? "h-6 text-[12px]" : "h-8 text-[13px]"
            } ${o.iconOnly ? (sm ? "w-6" : "w-8") : sm ? "px-2.5" : "px-3"} rounded-full ${pressed ? "text-foreground" : "text-muted-foreground hover:text-foreground"} ${INTERACTION_FOCUS}`}
          >
            {/* The fill: corners next to another pressed toggle square off so they read as one. */}
            <span
              aria-hidden="true"
              className="absolute inset-0 bg-[color-mix(in_oklab,var(--foreground)_9%,transparent)] transition-[scale] duration-200 group-active/tg:scale-[0.96] motion-reduce:group-active/tg:scale-100"
              style={{
                opacity: pressed ? 1 : 0,
                borderTopLeftRadius: left ? 4 : R,
                borderBottomLeftRadius: left ? 4 : R,
                borderTopRightRadius: right ? 4 : R,
                borderBottomRightRadius: right ? 4 : R,
                transition: reduced
                  ? "none"
                  : `opacity 220ms ${EASE_OUT}, border-radius 320ms ${EASE_OUT}, scale 200ms ${EASE_OUT}`,
              }}
            />
            <span className="relative inline-flex items-center gap-1.5">
              {o.icon}
              {!o.iconOnly && o.label}
            </span>
          </button>
        );
      })}
    </div>
  );
}

export interface ToggleProps extends Omit<
  React.ButtonHTMLAttributes<HTMLButtonElement>,
  "onChange"
> {
  pressed?: boolean;
  defaultPressed?: boolean;
  onPressedChange?: (pressed: boolean) => void;
  size?: "sm" | "md";
}

/** One pressed/unpressed button. Icon-only toggles need an aria-label. */
export function Toggle({
  pressed: controlled,
  defaultPressed = false,
  onPressedChange,
  size = "md",
  className = "",
  children,
  onClick,
  ...props
}: ToggleProps) {
  const reduced = useInteractionReducedMotion();
  const [own, setOwn] = React.useState(defaultPressed);
  const pressed = controlled ?? own;
  return (
    <button
      type="button"
      aria-pressed={pressed}
      onClick={(e) => {
        onClick?.(e);
        if (e.defaultPrevented) return;
        if (controlled === undefined) setOwn(!pressed);
        onPressedChange?.(!pressed);
      }}
      className={`group/tg relative inline-flex shrink-0 items-center justify-center gap-1.5 rounded-full font-medium cursor-pointer disabled:cursor-default disabled:opacity-40 [&_svg]:size-3.5 ${
        size === "sm"
          ? "h-7 min-w-7 px-2 text-[12px]"
          : "h-9 min-w-9 px-2.5 text-[13px]"
      } ${pressed ? "text-foreground" : "text-muted-foreground hover:bg-accent/50 hover:text-foreground"} ${INTERACTION_FOCUS} ${className}`}
      {...props}
    >
      <span
        aria-hidden="true"
        className="absolute inset-0 rounded-full bg-accent shadow-[inset_0_0_0_1px_var(--border)] transition-[scale] duration-200 group-active/tg:scale-[0.94] motion-reduce:group-active/tg:scale-100"
        style={{
          opacity: pressed ? 1 : 0,
          transition: reduced
            ? "none"
            : `opacity 220ms ${EASE_OUT}, scale 200ms ${EASE_OUT}`,
        }}
      />
      <span className="relative inline-flex items-center gap-1.5">
        {children}
      </span>
    </button>
  );
}

export default ToggleGroup;

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}

